    /// @return HRL_TRUE when the shape touches or overlaps at least one matching
    ///         voxel, otherwise HRL_FALSE.
    pub fn HRL_VoxelCheckCollision(sceneid: HRL_id, x: f32, y: f32, width: f32, height: f32, mask: u32, out_collision: *mut HRL_VoxelCollision) -> c_int;
